import{_ as a,H as e,f as r,i as t}from"./chunks/framework.Cvt1eIE0.js";const c=JSON.parse('{"title":"第五章 出発の朝","description":"","frontmatter":{},"headers":[],"relativePath":"story/6-2.md","filePath":"story/6-2.md"}'),o={name:"story/6-2.md"};function h(i,p,n,s,l,d){return e(),r("div",null,[...p[0]||(p[0]=[t('<h1 id="第五章-出発の朝" tabindex="-1">第五章 出発の朝 <a class="header-anchor" href="#第五章-出発の朝" aria-label="Permalink to &quot;第五章 出発の朝&quot;">​</a></h1><p>王国歴六十二年。</p><p>春の早朝。</p><p>「なぁ。」</p><p>スターリンが言った。</p><p>何の前置きもなく。お茶を一口飲んで、ケーキを半分食べてから。</p><p>「久しぶりに、冒険しねぇか。あの、青い空がある地上へさ」</p><p>「冒険？」</p><p>オーレックスは首を傾けた。</p><p>「そう。三人だけで。昔みたいに。護衛なし。大臣なし。旗なし。」</p><p>ピックバーグが本から顔を上げた。「腰が痛いんじゃなかったの？」</p><p>「冒険の前では痛くない。」</p><p>「何の理屈だ。」</p><p>「本能だ。」</p><p>「……どこへ行く。」</p><p>オーレックスが聞いた。</p><p>「大戦の時に、俺たち三人で駆け抜けた場所。全部さ。」</p><p>全部。</p><p>その一言が、胸に静かに落ちた。</p><p>石が、池の底に沈んでいくように。</p><p>「いいね。」</p><p>オーレックスは笑った。「行こう。」</p><p>「本当に？」</p><p>「うん。最後に。」</p><p>「最後？」</p><p>スターリンが不思議そうな顔をした。</p><p>「いや、なんでもないさ。さあ、まずは黒曜石戦争の時に作った、あの懐かしい『地上のゲート』へ向かおう」</p><p>王国の境界線にある巨大なネザーポータルの前に、三人は立っていた。</p><p>本来、ピグリンがオーバーワールドへ行けば、肉体が腐り、理性を失ったゾンビ（ゾンピグ）になってしまう。</p><p>それが世界の絶対的な掟だった。</p><p>しかし、オーレックスが歩み出ると、頭上の黄金の冠がかつてないほど強く、温かい光を放った。</p><p>かつて世界連合軍を結成し、エンダードラゴンから世界を救った際、黄金の冠は世界の調和の象徴として『地上でも理性を保ち、生きていられる力』を王とその親友たちに授けていたのだ。</p><p>「……いつ見ても、不思議な光だな」ピックバーグが眼鏡を押し上げる。</p><p>「がはは！ これなら地上でも美味いものが食えるってわけだ！ 行くぞ！」</p><p>紫色の揺らめくゲートを、三人は並んでくぐり抜けた。</p><hr><p>出発の朝。</p><p>夜明け前。</p><p>三人は王宮の門を出た。</p><p>誰にも告げなかった。ただ一人、リリアだけが知っていた。</p><p>バルコニーに立つ妻の姿が、振り返るたびに見えた。</p><p>オーレックスは最後に足を止め、振り返った。</p><p>リリアの顔には、「早く帰ってきて」とは書いていなかった。</p><p>「行ってきてください。」</p><p>そう、書いてあった。行くべき人の背中を、いつも止めなかった。それがリリアのやり方だった。心配しながら、それでも、見送る。そのことに、オーレックスは何十年も助けられてきた。</p><p>「行ってくる。」</p><p>「……うん。」</p><p>それだけ言って、オーレックスは歩き出した。</p><p>「なんか、懐かしいな。この感じ。」</p><p>スターリンが言った。「荷物が軽い感じ。建国前も、こうだったな。」</p><p>「あの頃は何にも持ってなかったけどな！」</p><p>「今もたいして変わらない。」</p><p>「じゃあ何も変わってない！」</p><p>「お前たちの頭の中は確かに変わってない。」</p><p>ピックバーグが言った。</p><p>三人は笑った。</p><p>笑いながら、歩き出した。</p><p>朝の光が、三人の長い影を後ろへ伸ばしていた。</p><hr><h1 id="第六章-辿り着いた場所" tabindex="-1">第六章 辿り着いた場所 <a class="header-anchor" href="#第六章-辿り着いた場所" aria-label="Permalink to &quot;第六章 辿り着いた場所&quot;">​</a></h1><p>最初に向かったのは、真紅の森の跡地だった。</p><p>かつて、炎が夜を染めた場所。</p><p>オーレックスの故郷。</p><p>「変わったなぁ。」</p><p>スターリンが辺りを見渡した。</p><p>「本当に。」</p><p>かつて炎に溶けた家々の跡地に、新しい家が建っていた。子供たちが走り回っていた。市場の声が聞こえた。あの夜の面影は、何一つ残っていなかった。</p><p>オーレックスはゆっくりと歩いた。</p><p>父の鍛冶場があった場所。 母がいつも笑っていた台所の辺り。 自分が仰向けに寝転んで、空を見上げていた、あの石畳。</p><p>今は全部、別の何かになっていた。</p><p>「……悲しいか？」</p><p>スターリンが、そっと聞いた。</p><p>「いや。」</p><p>オーレックスはゆっくりと首を振った。</p><p>「良かったと思う。ここが、こうなって。父さんも母さんも、きっとこれを望んでたと思うから。」</p><p>スターリンは何も言わなかった。</p><p>ただ、隣に立っていた。</p><p>あの炎の夜から、ずっとそうだったように。</p><p>それで、十分だった。</p><hr><p>次の日。</p><p>かつての古い砦跡に来た。</p><p>三人が初めて出会った、罠だらけの砦。</p><p>「懐かしいな……。」</p><p>スターリンが入口のアーチを見上げた。「四十五年前か。ここで出会った。」</p><p>「あの時のことを、今でも細かく覚えてる。」</p><p>ピックバーグが静かに言った。</p><p>「俺も。感圧板を踏んで矢が飛んできた。」</p><p>「飛んできたのはお前のせいだ。」</p><p>「でも矢は壁に刺さった。だから俺は無傷だ！」</p><p>「幸運だっただけ。」</p><p>「幸運も実力のうち！」</p><p>三人は笑った。</p><p>砦の内部は今や観光地になっていた。歴史遺産として整備され、案内板には「黄金王三人の出会いの地」と書かれていた。</p><p>「僕たちが展示物になってる。まだ生きてるのに。」</p><p>ピックバーグが呟いた。</p><p>「歴史って、そういうものだよ。」</p><p>「……そうか。」</p><p>オーレックスは、三人が最初に並んで歩いた石畳の上に立った。</p><p>あの日、ここを歩いた。三人で。</p><p>それが今も、ここにある。</p><p>石畳の冷たさが、靴の底から伝わってくる。四十五年前と、同じ冷たさで。</p><hr><p>その翌日。</p><p>旅の初めに立ち寄った、あの村へ来た。</p><p>盗賊団が食料を奪い、老人が諦めた顔で座り込んでいた、最初の村。スターリンが笑顔だけで盗賊を追い払った、あの村。</p><p>「大きくなった。もう村じゃない。」</p><p>石畳の市場。賑やかな声。笑い声。</p><p>「あの老人……どうなったかな。」</p><p>オーレックスが呟いた。</p><p>「俺もあの時のことは覚えてる。笑っただけで泣いてたじゃないか、あの老人。」</p><p>スターリンは市場の人々を眺めながら言った。</p><p>「当時は不思議だった。何もしてないのに、なぜそんなに泣くのかって。でも後から分かった。誰にも笑いかけてもらったことが、長い間なかったんだろうな。」</p><p>「……当たり前が、当たり前じゃない場所があった。あの頃は。」</p><p>ピックバーグが静かに言った。「だから旅に意味があった。」</p><p>三人は、賑やかな市場の端に立ったまま、しばらく人々を眺めていた。</p><p>誰も気づかない。三人が誰かを。ただの老人旅人が、市場を覗いている。</p><p>それでいい。それがいい。</p><p>笑い声の中に、あの老人の泣き顔が、重なって見えた気がした。</p><p>同じ場所の、別の時間。</p><p>両方が本物だった。</p><hr><h1 id="第七章-最後の焚き火" tabindex="-1">第七章 最後の焚き火 <a class="header-anchor" href="#第七章-最後の焚き火" aria-label="Permalink to &quot;第七章 最後の焚き火&quot;">​</a></h1><p>三日目の夜。</p><p>丘の上。</p><p>焚き火を囲んでいた。</p><p>満天の星。</p><p>「ここ、最初に野宿した場所に似てるな。」</p><p>スターリンが草の上に寝転がった。</p><p>「あの時は毛布が一枚しかなかった。」</p><p>「お前が独占した。」</p><p>「記録してあるから否定しないこと。」</p><p>スターリンは黙った。笑いをこらえながら、黙った。</p><p>「あの夜は寒かったな。食料も少なかった。何も持ってなかった。」</p><p>「何も……そうか。何もなかった。」</p><p>スターリンが炎を見た。揺れる炎を、じっと、静かに見た。</p><p>「今は。」</p><p>「腹いっぱいだ。温かい。隣に、友達がいる。」</p><p>「だから。」</p><p>「幸せだな。」</p><p>その言葉には、いつものような豪快さがなかった。</p><p>静かな声だった。低く、確かな声だった。</p><p>ピックバーグは本を閉じた。</p><p>オーレックスは炎を見た。</p><p>「建国して。黒曜石戦争して。エンダードラゴンと戦って。それでも今、こうして三人でいる。奇跡みたいな話だ。」</p><p>「そうだな。」</p><p>炎の音だけが、しばらく、会話の隙間を埋めた。</p><p>それから。</p><p>スターリンが、少し間を置いて言った。</p><p>「ありがとな。」</p><p>「二人とも。友達でいてくれて。」</p><p>「……。」</p><p>沈黙。</p><p>こんな言葉を、スターリンが言うのは珍しかった。</p><p>いや、珍しくはなかった。思えば大事な夜には、いつもこういう言葉を、この男は口にしてきた。照れながら、笑いで包みながら。</p><p>しかし今夜は違った。</p><p>笑いがなかった。ただ、真っ直ぐだった。</p><p>「こっちこそ。」</p><p>オーレックスは言った。「お前みたいな親友、他に一人もいない。」</p><p>「俺も。」</p><p>「僕も。」</p><p>ピックバーグが言った。「感謝してる。二人に。友達というものを教えてもらった。」</p><p>「お前が言うか。」</p><p>「僕が言う。」</p><p>「五十年かかったけどな。」</p><p>「うん。五十年かかったけど、確かに、学んだ。」</p><p>スターリンは笑った。</p><p>初めは小さく、それから豪快に、いつものように笑った。その笑い声が夜空に広がった。炎が揺れた。どこかで虫が鳴いた。</p><p>そして。</p><p>「腹いっぱいだし。いい話もしたし。俺、先に寝る。」</p><p>「早い。」</p><p>「満足したら眠い。」</p><p>「それは本当に単純だね。」</p><p>「単純で何が悪い。」</p><p>スターリンは帽子を目深に被り、草の上に横になった。大きな背中が、炎の光に浮かんだ。</p><p>「スターリン。」</p><p>オーレックスが言った。</p><p>「ん？」</p><p>「おやすみ。」</p><p>「ああ。」</p><p>少し間があった。</p><p>「おやすみ。また話そうな。絶対また。」</p><p>「うん。」</p><p>「絶対な。」</p><p>「……ああ。絶対な。」</p><p>その言葉が、夜の空に消えた。</p><p>炎が、ゆっくりと小さくなった。</p><p>ネザーの狭い天井には決してない、地上のどこまでも広大な夜空に、星が一つ一つ白く輝いていた。</p><p>オーレックスとピックバーグは、しばらく無言で炎を見ていた。言う必要がなかった。言葉にしてしまうと、何かが崩れる気がした。</p><p>やがて炎が消えた。</p><p>闇の中で、星だけが残った。</p><hr><h1 id="第八章-親友" tabindex="-1">第八章 親友 <a class="header-anchor" href="#第八章-親友" aria-label="Permalink to &quot;第八章 親友&quot;">​</a></h1><p>朝。</p><p>ネザーには決してない、冷涼で澄んだ空気が三人を包んでいた。</p><p>草の露が、朝の光を丸く受けて光っていた。</p><p>小鳥が鳴いていた。</p><p>ピックバーグが目を覚ました。</p><p>空を見た。青かった。</p><p>隣を見た。</p><p>スターリンが、変わらない姿勢で横になっていた。帽子をかぶったまま。昨夜と同じ、穏やかな顔で。</p><p>ピックバーグはしばらく、その顔を見ていた。</p><p>研究者の目で、見た。</p><p>そして。</p><p>静かに、オーレックスの肩を揺すった。</p><p>「オーレックス。」</p><p>「ん……。」</p><p>「起きて。」</p><p>オーレックスは目を開けた。青い空。草の匂い。</p><p>「スターリン。」</p><p>オーレックスは、肩に手を置いた。</p><p>「朝だよ。」</p><p>返事はなかった。</p><p>「スターリン。」</p><p>もう一度、呼んだ。</p><p>返事はなかった。</p><p>風だけが、草を揺らしていた。</p><p>長い、長い時間が流れた気がした。実際には数十秒だったかもしれない。それでも、長かった。</p><p>「……。」</p><p>ピックバーグは、帽子を取った。眼鏡を外した。目元を、静かに拭った。</p><p>研究者は事実を記録する。だから、涙は一瞬だけ許した。一瞬だけ。</p><p>オーレックスは、スターリンの手を握った。</p><p>まだ少し、温かかった。</p><p>その温もりが、朝の空気に、ゆっくりと溶けていった。</p><p>「……最後まで。」</p><p>ピックバーグが言った。声が、わずかに震えていた。</p><p>「君らしいね。騒がしく生きて、静かに眠るなんて。」</p><p>「帽子まで被ったままで。」</p><p>長い沈黙。</p><p>やがて、オーレックスは顔を上げた。</p><p>空を見た。青い空。雲がない。</p><p>「ありがとう。」</p><p>「親友。」</p><p>「また。」</p><p>「いつか。」</p><p>「会おう。」</p><p>その言葉が空に消えると同時に、風が吹いた。</p><p>草が揺れた。</p><p>まるで。</p><p>『おう！またな！待ってるぞ！』</p><p>という、あの豪快な声が、遠くから転がってくるような気がした。</p><hr><p>彼らはその丘に、スターリンを葬った。</p><p>星がよく見える場所に。 彼が好きだった、大きな木の下に。</p><p>墓標は、石一つだけ。</p><p>飾らない。派手なものは何もいらない。豪快に生きた男には、豪快に眠れる場所があれば、十分だった。</p><p>帰り道は、長かった。</p><p>二人になった帰り道は、行きより倍の時間がかかるように感じた。</p><p>歩き方は変わっていない。</p><p>ただ。</p><p>隣に、あの笑い声がなかった。</p><p>それだけで、道が変わった。</p><p>王都の門が見えた時、バルコニーにリリアが立っていた。</p><p>何も言わなかった。ただ、オーレックスの顔を見て、全てを理解した。</p><p>すぐに降りてきて、夫の手を握った。</p><p>それだけだった。それで、十分だった。</p>',256)])])}const f=a(o,[["render",h]]);export{c as __pageData,f as default};
